import {ToolRegistry} from './registry.js';

describe('tool validation paths', () => {
  // specs/hal-engine-tool-input-validation/spec.md#1
  it('escapes a missing property name in its JSON pointer path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'weather', inputSchema: {type: 'object', required: ['a/b~c']}},
      async () => 'forecast'
    );
    const response = await registry.execute('weather', {});
    expect(response.result).toBe('Invalid tool input: /a~1b~0c is required');
  });
});
EOF
